	scwin.onpageload = function() {
		dlt_Menu.setJSON(scwin.jsonData.dlt_Menu);

		//데이터 변경

		dlt_Menu.setCellData(3, "menu_nm", "메뉴명변경1");
		dlt_Menu.setCellData(4, "menu_nm", "메뉴명변경2");
		dlt_Menu.setCellData(5, "menu_nm", "메뉴명변경3");
