	scwin.onpageunload = function() {
	};

	scwin.gridView1_ongroupby = function(options) {
		debugger;
		options.rowNumHeader = { inputType: 'expression', expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "', align: 'left', colSpan:5 };
		options.rowNumFooter = {colSpan:3};
		options.rowStatusFooter = {value:'합계'};
		options.groupbyFooter = [ { inputType: 'expression', expression:'SUM("menu_level")'} ];

		gridView1.groupby(options);	
	};

	scwin.btn_trigger1_onclick = function(e) {
		var options = {
			sortIndex : [2],
			sortOrder : [1],
			hideHeader : false,
			hideFooter : true,
			groupbyHeader : {
				depth_0 : [{
					colSpan : "3",
					value : "레벨 합계"
				}, {
					inputType : "expression",
					expression : " SUM('menu_level')"
				}]
			}
		};
		gridView1.groupby(options);
	};

	scwin.btn_trigger2_onclick = function(e) {
		gridView1.clearGroupby();
	};

	function unitTest(){
		//Unit test
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");

        WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_headerRowStatus_bodyRow_4').hasClass('w2grid_rowStatus_U')", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run and Stop test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	unitTest();
